 RectTransform Rect(Transform p,string name,Vector2 min,Vector2 max,Vector2 pos,Vector2 size){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=min;r.anchorMax=max;r.pivot=(min==max?min:new Vector2(.5f,.5f));r.anchoredPosition=pos;r.sizeDelta=size;return r;}
