 Transform Row(Transform p,float h){var g=new GameObject("Row",typeof(RectTransform),typeof(HorizontalLayoutGroup),typeof(LayoutElement));g.transform.SetParent(p,false);g.GetComponent<LayoutElement>().preferredHeight=h;var l=g.GetComponent<HorizontalLayoutGroup>();l.spacing=12;l.childForceExpandHeight=true;l.childForceExpandWidth=true;return g.transform;}
