  var scaler=root.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1280,720);scaler.screenMatchMode=CanvasScaler.ScreenMatchMode.Expand;
  safe=Rect(root.transform,"SafeArea",Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero);var area=Screen.safeArea;safe.anchorMin=new Vector2(area.xMin/width,area.yMin/height);safe.anchorMax=new Vector2(area.xMax/width,area.yMax/height);
