  var design=Page();pages[0]=design.gameObject;var missions=Row(design,H);var previous=Button(missions,"◀",()=>{app.SelectMission((app.Configuration.mission+5)%6);});previous.GetComponent<LayoutElement>().flexibleWidth=0;previous.GetComponent<LayoutElement>().preferredWidth=H;
  var confirm=Button(missions,"",()=>app.SelectMission(app.Configuration.mission));missionLabel=confirm.GetComponentInChildren<Text>();var next=Button(missions,"▶",()=>app.SelectMission((app.Configuration.mission+1)%6));next.GetComponent<LayoutElement>().flexibleWidth=0;next.GetComponent<LayoutElement>().preferredWidth=H;
  conditions=Label(design,"",Mathf.Max(110,55/scale),27);resources=Label(design,"",Mathf.Max(85,40/scale),27);
