  for(int i=0;i<3;i++){int chosen=i;options[i]=Button(design,"",()=>app.SelectComponent(category,chosen));options[i].GetComponent<LayoutElement>().preferredHeight=Mathf.Max(155,94/scale);optionLabels[i]=options[i].GetComponentInChildren<Text>();optionLabels[i].alignment=TextAnchor.MiddleLeft;}
  Button(design,"Añadir / quitar segundo instrumento",()=>{if(app.Configuration.mission==4)app.ToggleSecondInstrument();}).name="TouchSecondaryInstrument";
  var actions=Row(design,H);assemble=Button(actions,"ENSAMBLAR",()=>station.StartAssembly());launch=Button(actions,"Lanzar",()=>app.SendMessage("Launch"));
  Button(design,"Rediseñar",()=>{if(!station.Busy)app.SendMessage("ResetDesign");});
  var data=Page();pages[1]=data.gameObject;Label(data,"CARONTE / TELEMETRÍA Y ARQUITECTURA",H,31);
  var pg=new GameObject("TouchPreviewFrame",typeof(RectTransform),typeof(LayoutElement));pg.transform.SetParent(data,false);pg.GetComponent<LayoutElement>().preferredHeight=Mathf.Max(390,210/scale);
  var picture=Rect(pg.transform,"TouchSatellitePreview",Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero);preview=picture.gameObject.AddComponent<RawImage>();preview.texture=station.previewTexture;var fit=picture.gameObject.AddComponent<AspectRatioFitter>();fit.aspectMode=AspectRatioFitter.AspectMode.FitInParent;fit.aspectRatio=station.previewTexture?(float)station.previewTexture.width/station.previewTexture.height:16f/9f;var surface=picture.gameObject.AddComponent<MobileTouchSurface>();surface.kind=TouchSurfaceKind.Preview;surface.app=app;
  Label(data,"Arrastra para girar el CanSat",Mathf.Max(58,28/scale),27);telemetry=Label(data,"",Mathf.Max(220,110/scale),29);
  var speedRow=Row(data,H);Button(speedRow,"Pausa / continuar",()=>app.TogglePause());Button(speedRow,"Velocidad ×",()=>app.SetSimulationSpeed(app.SimulationSpeed>=3600?60:app.SimulationSpeed*10));Button(speedRow,"Completar",()=>app.CompleteSimulation());
  var camera=Page();pages[2]=camera.gameObject;Label(camera,"CARONTE / CÁMARA DE A BORDO",H,31);
  var vg=new GameObject("TouchVideoFrame",typeof(RectTransform),typeof(LayoutElement));vg.transform.SetParent(camera,false);vg.GetComponent<LayoutElement>().preferredHeight=Mathf.Max(430,210/scale);var videoRect=Rect(vg.transform,"TouchOrbitalVideo",Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero);video=videoRect.gameObject.AddComponent<RawImage>();video.raycastTarget=false;var vf=videoRect.gameObject.AddComponent<AspectRatioFitter>();vf.aspectMode=AspectRatioFitter.AspectMode.FitInParent;vf.aspectRatio=16f/9f;videoStatus=Label(camera,"",Mathf.Max(100,50/scale),29);fragments=Label(camera,"",Mathf.Max(340,170/scale),30);
  continueNext=Button(scroll.content,"CONTINUAR CON LA SIGUIENTE MISIÓN",()=>{if(control)control.ContinueToNextMission();});continueNext.gameObject.SetActive(false);
  menu=new GameObject("TouchMenu",typeof(RectTransform));menu.transform.SetParent(safe,false);var mr=menu.GetComponent<RectTransform>();mr.anchorMin=Vector2.zero;mr.anchorMax=Vector2.one;mr.sizeDelta=Vector2.zero;
  At(menu.transform,"Diseño",new Vector2(.5f,1),new Vector2(-282,-10),new Vector2(176,H),()=>ShowPage(0));
  At(menu.transform,"CanSat",new Vector2(.5f,1),new Vector2(-94,-10),new Vector2(176,H),()=>ShowPage(1));
  At(menu.transform,"Video",new Vector2(.5f,1),new Vector2(94,-10),new Vector2(176,H),()=>ShowPage(2));
  At(menu.transform,"Pausa",new Vector2(1,1),new Vector2(-12,-10),new Vector2(155,H),()=>room.SetPaused(!room.IsPaused));
  var sr=Rect(menu.transform,"MissionStatus",new Vector2(0,1),Vector2.one,new Vector2(0,-H-40),new Vector2(-30,58));status=sr.gameObject.AddComponent<LocalizedText>();Style(status,"",27);status.alignment=TextAnchor.MiddleCenter;
  interact=At(menu.transform,"Consola",new Vector2(0,1),new Vector2(12,-10),new Vector2(176,H),()=>station.ToggleTouchConsole());
  explore=new GameObject("TouchExploration",typeof(RectTransform));explore.transform.SetParent(safe,false);var er=explore.GetComponent<RectTransform>();er.anchorMin=Vector2.zero;er.anchorMax=Vector2.one;er.sizeDelta=Vector2.zero;explore.transform.SetAsFirstSibling();
  var look=Box(explore.transform,"LookPad",new Vector2(.48f,.2f),new Vector2(1,.86f),Vector2.zero,Vector2.zero,new Color(0,0,0,.005f));look.gameObject.AddComponent<MobileTouchSurface>().kind=TouchSurfaceKind.Look;FillText(look,"Arrastra para mirar",25).color=new Color(.7f,.9f,1,.4f);
  float stickSize=Mathf.Max(210,112/scale);var stick=Box(explore.transform,"Joystick",Vector2.zero,Vector2.zero,new Vector2(32,26),new Vector2(stickSize,stickSize),new Color(.02f,.15f,.23f,.55f));stick.pivot=Vector2.zero;
  var knob=Box(stick,"Thumb",new Vector2(.5f,.5f),new Vector2(.5f,.5f),Vector2.zero,new Vector2(stickSize*.32f,stickSize*.32f),new Color(.15f,.75f,.9f,.8f));knob.GetComponent<Image>().raycastTarget=false;
  var mover=stick.gameObject.AddComponent<MobileTouchSurface>();mover.kind=TouchSurfaceKind.Move;mover.knob=knob;
  upDown=new GameObject("TouchZeroGravity",typeof(RectTransform));upDown.transform.SetParent(explore.transform,false);var ur=upDown.GetComponent<RectTransform>();ur.anchorMin=Vector2.zero;ur.anchorMax=Vector2.one;ur.sizeDelta=Vector2.zero;
  var up=At(upDown.transform,"Subir",new Vector2(1,0),new Vector2(-22,H+44),new Vector2(180,H),()=>{});up.gameObject.AddComponent<MobileTouchSurface>().kind=TouchSurfaceKind.Up;
  var down=At(upDown.transform,"Bajar",new Vector2(1,0),new Vector2(-22,24),new Vector2(180,H),()=>{});down.gameObject.AddComponent<MobileTouchSurface>().kind=TouchSurfaceKind.Down;
  var bar=Box(consolePanel.transform,"ScrollBar",new Vector2(1,0),Vector2.one,Vector2.zero,new Vector2(9,0),new Color(.03f,.12f,.18f));bar.offsetMin=new Vector2(-12,Mathf.Max(142,90/scale));bar.offsetMax=new Vector2(-3,-H-78);var sb=bar.gameObject.AddComponent<Scrollbar>();sb.direction=Scrollbar.Direction.BottomToTop;var handle=Box(bar,"Handle",Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero,new Color(.15f,.8f,.85f));sb.handleRect=handle;sb.targetGraphic=handle.GetComponent<Image>();scroll.verticalScrollbar=sb;
  ShowPage(page);revision=null;
 }
 void ChooseCategory(int i){category=(i+11)%11;var design=GetComponent<MissionDesignPanel>();if(design)design.FocusCategory(category);revision=null;}
 public void ShowPage(int index){page=Mathf.Clamp(index,0,2);for(int i=0;i<3;i++)if(pages[i])pages[i].SetActive(i==page);if(scroll){Canvas.ForceUpdateCanvases();scroll.verticalNormalizedPosition=1;}}
 void AdaptExistingOverlays(){
  var mission=transform.Find("MissionControlOverlay");if(mission){mission.GetComponent<Canvas>().sortingOrder=3600;mission.GetComponent<CanvasScaler>().referenceResolution=new Vector2(1280,720);var deadline=mission.Find("LaunchDeadline");if(deadline)deadline.gameObject.SetActive(false);var sub=mission.Find("IntercomSubtitles") as RectTransform;if(sub){sub.anchoredPosition=new Vector2(0,12);sub.sizeDelta=new Vector2(1160,Mathf.Max(118,70/scale));foreach(var t in sub.GetComponentsInChildren<Text>()){t.resizeTextMaxSize=Mathf.Max(t.resizeTextMaxSize,Mathf.RoundToInt(15/scale));t.fontSize=t.resizeTextMaxSize;}}var success=mission.Find("MissionSuccess") as RectTransform;if(success)success.anchoredPosition=new Vector2(0,-H-90);}
  var pause=GameObject.Find("StationGlobalUI");if(pause){pause.GetComponent<CanvasScaler>().referenceResolution=new Vector2(1280,720);var card=pause.transform.Find("PauseMenu/PauseCard") as RectTransform;if(card){card.sizeDelta=new Vector2(560,560);string[] names={"Continuar","Reiniciar","Salir"};for(int i=0;i<3;i++){var b=card.Find(names[i]) as RectTransform;if(b){b.anchoredPosition=new Vector2(0,-120-i*108);b.sizeDelta=new Vector2(410,88);}}foreach(var t in card.GetComponentsInChildren<Text>())if(t.text.Contains("Esc ")||t.text.Contains("Reinicie")){t.rectTransform.anchoredPosition=new Vector2(0,-462);t.rectTransform.sizeDelta=new Vector2(480,70);}}}
 }
 void LateUpdate(){
  if(!root||!station||!app)return;if(width!=Screen.width||height!=Screen.height){Build();AdaptExistingOverlays();}
  bool paused=room&&room.IsPaused;consolePanel.SetActive(station.ConsoleActive&&!paused);explore.SetActive(!station.ConsoleActive&&!paused);menu.SetActive(!paused);
  // Only the view buttons belong to the open console; Pause and Interact remain available while exploring.
  for(int i=0;i<3;i++)menu.transform.GetChild(i).gameObject.SetActive(station.ConsoleActive);
  interact.gameObject.SetActive(station.ConsoleActive||station.CanInteractWithConsole);interact.GetComponentInChildren<Text>().text=station.ConsoleActive?"Explorar":"Consola";upDown.SetActive(room&&room.RoomDestroyed);
  if(control){int seconds=Mathf.CeilToInt(control.Remaining);status.text=(Screen.height>Screen.width?"Gira el dispositivo para ver mejor · ":"")+MissionCatalog.Missions[control.AssignedMission].name+" · "+(control.Phase==ControlPhase.Designing?(seconds/60).ToString("00")+":"+(seconds%60).ToString("00"):control.Phase==ControlPhase.Briefing?"TUTORIAL":control.Terminal?"MISIÓN FALLIDA":control.Phase==ControlPhase.Launched?"LANZADO":control.Phase==ControlPhase.Verifying?"VERIFICANDO":"COMPLETADA");}
  if(!station.ConsoleActive||paused)return;var c=app.Configuration;if(control&&control.IsTutorial&&control.TutorialCategory>=0)category=control.TutorialCategory;
  string now=JsonUtility.ToJson(c)+category+(control?control.MissionConfirmed.ToString():"")+GameLanguage.English;if(now!=revision){revision=now;DrawDesign();}
  bool ready=(!control||control.CanAssemble)&&app.Stage==1&&!station.Busy;assemble.interactable=ready;launch.interactable=ready&&station.Assembled;foreach(var b in options)b.interactable=app.Stage==1&&!station.Busy;
  var extra=pages[0].transform.Find("TouchSecondaryInstrument");if(extra)extra.gameObject.SetActive(c.mission==4&&category==1);
  continueNext.gameObject.SetActive(control&&control.AwaitingContinuation);var engine=app.CurrentEngine;
  telemetry.text=app.telemetry.text+"\n\n"+(engine!=null?"BATERÍA "+engine.Energy.ToString("0.0")+" Wh\nCapturados "+engine.Result.captured.ToString("0")+" MB · enviados "+engine.Result.sent.ToString("0")+" MB\nÚtiles "+engine.Result.useful.ToString("0")+" MB":"MASA "+c.Mass.ToString("0.0")+" kg · PRESUPUESTO "+c.Cost+" cr\nPOTENCIA MEDIA "+c.AverageGeneration.ToString("0")+" W · CONSUMO "+c.Load+" W\nBATERÍA "+c.Capacity+" Wh · PROPELENTE "+c.Propellant.ToString("0.0")+" kg");
  if(feed){video.texture=feed.videoTexture;video.enabled=feed.SignalAvailable;videoStatus.text=feed.SignalAvailable?"● EN DIRECTO / "+(engine!=null?engine.MissionClock:""):"SIN SEÑAL\nESPERANDO INSERCIÓN ORBITAL";}
  string message="TRANSMISIÓN RECUPERADA  /  "+(presentation?presentation.UnlockedCount:0)+" DE 6 FRAGMENTOS\n";for(int i=0;i<6;i++)message+="\n"+(presentation&&presentation.unlocked[i]?"[✓] "+MissionPresentation.Fragments[i]:"[···]")+"  ";
  if(control&&control.Terminal)message="MISIÓN FALLIDA\n"+control.FailureDetails;fragments.text=message;
 }
 void DrawDesign(){var c=app.Configuration;missionLabel.text="MISIÓN "+(c.mission+1)+"/6 · "+c.Mission.name+(control&&control.MissionConfirmed?" ✓":" · CONFIRMAR");conditions.text=c.Mission.conditions+"\n"+c.Mission.goal;resources.text="MASA "+c.Mass.ToString("0.0")+" / "+c.MaxMass+" kg · PRESUPUESTO "+c.Cost+" / "+c.Mission.budget+" cr\nPOTENCIA MEDIA "+c.AverageGeneration.ToString("0")+" W / "+c.Load+" W · BATERÍA "+c.Capacity+" Wh";categoryLabel.text=(category+1)+"/11 · "+MissionCatalog.Categories[category];
  for(int i=0;i<3;i++){var o=MissionCatalog.Options[category][i];optionLabels[i].text=(c.choices[category]==i?"[✓] ":"")+o.name+" · "+o.cost+" cr / "+o.mass+" kg\n"+o.criterion+"\n"+o.impact;options[i].GetComponent<Image>().color=c.choices[category]==i?new Color(.035f,.36f,.35f):new Color(.04f,.15f,.23f);}
 }
 void OnApplicationFocus(bool focus){if(!focus)MobileRuntime.Clear();}
 void OnApplicationPause(bool pause){if(pause)MobileRuntime.Clear();}
 void OnDisable(){MobileRuntime.Clear();}
 void OnDestroy(){if(root)Destroy(root);}
}
